package com.truckload.controller;
import java.util.*;
/** Validated controller records; region-list replacement is atomic on complete readback. */
public final class GeoModel {
 public static final String[] STATES={"DRIVING","STOPPED","NO_FIX"},PATTERNS={"SOLID","PULSE","CHASE","ALTERNATE","BREATHE","RAINBOW","COMET","SCANNER","WAVE","AURORA","THEATER","GROUND"};
 public static final String[] PATTERN_NAMES={"Solid","Gentle pulse","Smooth chase","Crossfade alternating","Breathing","Rainbow","Comet trail","Scanner sweep","Color wave","Aurora","Theater chase","Ground speed"},MODE_NAMES={"Load indication","Driving effect","Work lights","Off","Use underlying rule / normal lighting"};
 public static class Point{public double lat,lon;public Point(double a,double b){lat=a;lon=b;}}
 public static class Action{public int mode=4,pattern=0,brightness=140;public String primary="000028",secondary="FFA500";public Action copy(){Action a=new Action();a.mode=mode;a.pattern=pattern;a.brightness=brightness;a.primary=primary;a.secondary=secondary;return a;}public String wire(){return mode+"|"+pattern+"|"+primary+"|"+secondary+"|"+brightness;}}
 public static class Area{public int id,priority=10,radius=50,expectedPoints;public boolean enabled=true;public String name="",shape="C";public List<Point> points=new ArrayList<>();public Action[] actions={new Action(),new Action()};boolean[] received=new boolean[2];public Area copy(){Area a=new Area();a.id=id;a.priority=priority;a.radius=radius;a.enabled=enabled;a.name=name;a.shape=shape;for(Point p:points)a.points.add(new Point(p.lat,p.lon));a.actions[0]=actions[0].copy();a.actions[1]=actions[1].copy();return a;}}
 public boolean ready,enabled,manualOverride,active,pending,groundFresh;public int dwell=2500,margin=5,spacing=1500,width=350,activeId=-1,revision;public double stopped=1,driving=3,speed=Double.NaN,distance;public boolean[] reverse={false,false};public int[] offset={0,0};public String control="OFF",source="Outside saved areas",motion="NO_FIX",error="";public Action activeAction=new Action();public Action[] fallback={new Action(),new Action(),new Action()};public List<Area> areas=new ArrayList<>();public long stateAt,groundAt;private Map<Integer,Area> incoming;private boolean badList;
 static int integer(String s,int low,int high){if(!s.matches("-?[0-9]+"))throw new IllegalArgumentException();int n=Integer.parseInt(s);if(n<low||n>high)throw new IllegalArgumentException();return n;}static double number(String s,double low,double high){double n=Double.parseDouble(s);if(!Double.isFinite(n)||n<low||n>high)throw new IllegalArgumentException();return n;}static int state(String s){return Arrays.asList(STATES).indexOf(s);}static boolean hex(String s){return s.matches("[0-9a-fA-F]{6}");}
 public static boolean validPoint(Point p){return Double.isFinite(p.lat)&&Double.isFinite(p.lon)&&Math.abs(p.lat)<=85&&Math.abs(p.lon)<=180;}
 static Action action(String[] x,int at){if(x.length<at+5)throw new IllegalArgumentException();Action a=new Action();a.mode=integer(x[at],0,4);a.pattern=integer(x[at+1],0,a.mode==0?3:11);if(!hex(x[at+2])||!hex(x[at+3]))throw new IllegalArgumentException();a.primary=x[at+2].toUpperCase(Locale.US);a.secondary=x[at+3].toUpperCase(Locale.US);a.brightness=integer(x[at+4],1,255);return a;}
 public boolean apply(String line,long now){String[] x=line.split("\\|",-1);try{switch(x[0]){
 case "GEO_CONFIG":if(x.length!=9)throw new IllegalArgumentException();boolean en=integer(x[1],0,1)==1,manual=integer(x[2],0,1)==1;int delay=integer(x[3],0,10000),edge=integer(x[4],0,50);double stop=number(x[5],0,20),drive=number(x[6],.1,30);if(drive<=stop||integer(x[7],1,12)!=12||integer(x[8],1,12)!=12)throw new IllegalArgumentException();enabled=en;manualOverride=manual;dwell=delay;margin=edge;stopped=stop;driving=drive;ready=true;revision++;return true;
 case "GEO_FALLBACK":{if(x.length!=7)throw new IllegalArgumentException();int i=state(x[1]);if(i<0)throw new IllegalArgumentException();fallback[i]=action(x,2);revision++;return true;}
 case "GROUND_CONFIG":if(x.length!=7)throw new IllegalArgumentException();int s=integer(x[1],100,10000),w=integer(x[2],20,10000);if(w>s)throw new IllegalArgumentException();boolean a=integer(x[3],0,1)==1,b=integer(x[4],0,1)==1;int o=integer(x[5],-10000,10000),p=integer(x[6],-10000,10000);spacing=s;width=w;reverse[0]=a;reverse[1]=b;offset[0]=o;offset[1]=p;revision++;return true;
 case "GEO_STATE":if(x.length!=12||!Arrays.asList("OFF","PAUSED","AUTO").contains(x[1])||state(x[4])<0)throw new IllegalArgumentException();Action aa=action(x,5);int id=integer(x[2],-1,11);boolean ac=integer(x[10],0,1)==1,pe=integer(x[11],0,1)==1;control=x[1];activeId=id;source=x[3];motion=x[4];activeAction=aa;active=ac;pending=pe;stateAt=now;return true;
 case "GROUND_STATE":if(x.length!=4)throw new IllegalArgumentException();boolean fresh=integer(x[1],0,1)==1;double velocity=fresh?number(x[2],0,200):Double.NaN,travel=number(x[3],0,1e12);groundFresh=fresh;speed=velocity;distance=travel;groundAt=now;return true;
 case "GEO_LIST_BEGIN":incoming=new TreeMap<>();badList=false;return false;
 case "GEO_AREA":{if(incoming==null||x.length!=8)throw new IllegalArgumentException();Area area=new Area();area.id=integer(x[1],0,11);area.name=x[2];if(area.name.isEmpty()||area.name.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>24)throw new IllegalArgumentException();area.priority=integer(x[3],0,100);area.enabled=integer(x[4],0,1)==1;if(!x[5].equals("C")&&!x[5].equals("P"))throw new IllegalArgumentException();area.shape=x[5];area.radius=integer(x[6],5,5000);area.expectedPoints=integer(x[7],1,12);if(incoming.containsKey(area.id))throw new IllegalArgumentException();incoming.put(area.id,area);return false;}
 case "GEO_VERTEX":{if(incoming==null||x.length!=4)throw new IllegalArgumentException();Area area=incoming.get(integer(x[1],0,11));if(area==null||area.points.size()>=12)throw new IllegalArgumentException();area.points.add(new Point(number(x[2],-85,85),number(x[3],-180,180)));return false;}
 case "GEO_AREA_ACTION":{if(incoming==null||x.length!=8)throw new IllegalArgumentException();Area area=incoming.get(integer(x[1],0,11));int i=state(x[2]);if(area==null||i<0||i>1)throw new IllegalArgumentException();area.actions[i]=action(x,3);area.received[i]=true;return false;}
 case "GEO_LIST_END":if(incoming==null||badList)throw new IllegalArgumentException();for(Area area:incoming.values())if(area.points.size()!=area.expectedPoints||!area.received[0]||!area.received[1]||(area.shape.equals("C")?area.points.size()!=1:area.points.size()<3))throw new IllegalArgumentException();areas=new ArrayList<>(incoming.values());incoming=null;revision++;return true;
 default:return false;
 }}catch(RuntimeException e){if(incoming!=null)badList=true;error="Incomplete or invalid location settings; refresh from controller.";return false;}}
 public int freeId(){for(int i=0;i<12;i++){boolean found=false;for(Area a:areas)if(a.id==i)found=true;if(!found)return i;}return -1;}
}
